-- KRL Kranji and Cakung exits, coordinates and signage taken on site (source = 'FIELD').
--
-- The platform signs say only A and B; A1/A2 (and Cakung's B1/B2) are two
-- staircases to the same side, so each pair is one exit here, named as signed.
-- Its point is the midpoint of the two staircases (about 25 m apart). No `kind`
-- or `stationId` yet; `name` stays NULL. Idempotent; needs 0017 and 0018.
-- Apply BEFORE the deploy, then bump API_VERSION.
INSERT INTO stationExits (id, stationId, ref, name, latitude, longitude, signs, source, createdAt, updatedAt) VALUES ('KCI-KRI:A', 'KCI-KRI', 'A', NULL, -6.224589, 106.979715, '[{"text":"Jl. Jenderal Sudirman - Pantura"},{"text":"Naga Swalayan Kranji"},{"text":"Pasar Kranji Lama (Pertokoan)"},{"text":"Jl. Pemuda Kranji"}]', 'FIELD', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT(id) DO UPDATE SET latitude = excluded.latitude, longitude = excluded.longitude, signs = excluded.signs, source = 'FIELD', updatedAt = CURRENT_TIMESTAMP;
INSERT INTO stationExits (id, stationId, ref, name, latitude, longitude, signs, source, createdAt, updatedAt) VALUES ('KCI-KRI:B', 'KCI-KRI', 'B', NULL, -6.224289, 106.97987, '[{"text":"Jl. Melati Raya"},{"text":"Jl. Kalibaru Timur"},{"text":"SMA Patriot Bekasi"},{"text":"SMK Patriot Bekasi 2"}]', 'FIELD', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT(id) DO UPDATE SET latitude = excluded.latitude, longitude = excluded.longitude, signs = excluded.signs, source = 'FIELD', updatedAt = CURRENT_TIMESTAMP;
